UPDATE alphafrog_agent_run_coordination SET
    coordination_missed_rounds = GREATEST(#{roundNumber} - coordination_served_round - 1, 0),
    updated_at = CURRENT_TIMESTAMP
WHERE scheduler_version = #{schedulerVersion}
  AND coordination_served_round < #{roundNumber}

UPDATE alphafrog_agent_run_coordination SET
    dispatch_missed_rounds = GREATEST(#{roundNumber} - dispatch_served_round - 1, 0),
    updated_at = CURRENT_TIMESTAMP
WHERE scheduler_version = #{schedulerVersion}
  AND dispatch_served_round < #{roundNumber}
